{"source":"#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b){
    return(*(int*)a - *(int*)b);
}

int main(int argc, char *argv[]){
    int n, i, time;
    int j = 1;
    int max = 0;
    scanf("%d", &n);
    int t[n];
    for(i=0;i<n;i++) scanf("%d", &t[i]);
    scanf("%d", &time);
    qsort(t, n, sizeof(int), cmp);
    for(i=0;i<n;i++){
        j = 1;
        while(i+j<n && t[i+j]-t[i] <= time){j++;}
        if(max<j) max = j;
    }
    printf("%d\n", max);
    return 0;
}
